def note(name, desc, ntype, pad=4, le=True):
    end = '<' if le else '>'
    def align(b):
        return b + b'\0' * ((-len(b)) % pad)
    return struct.pack(end+'III', len(name), len(desc), ntype) + align(name) + align(desc)
def mknote(content, extra_phdrs=[], **kw):
    off = 0x200
