use crate::ranges::{RangeType, Ranges};

pub const ELFCLASS32: u8 = 1;
pub const ELFCLASS64: u8 = 2;
pub const ELFDATA2LSB: u8 = 1;
pub const ELFDATA2MSB: u8 = 2;

pub const PT_INTERP: u32 = 3;
pub const PT_NOTE: u32 = 4;
pub const SHT_STRTAB: u32 = 3;
pub const SHT_NOBITS: u32 = 8;

pub struct Ident {
    pub class: u8,
    pub data: u8,
    pub version: u8,
    pub abi: u8,
    pub abi_ver: u8,
}

pub struct Ehdr {
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

pub struct Phdr {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

pub struct Shdr {
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
}

pub struct Note {
    pub name: Vec<u8>,
    pub desc: Vec<u8>,
    pub ntype: u32,
}

pub struct Elf {
    pub ident: Ident,
    pub ehdr: Ehdr,
    pub phdrs: Vec<Phdr>,
    pub shdrs: Vec<Shdr>,
    pub section_names: Vec<String>,
    /// Parsed notes for every program header (empty for non-NOTE segments).
    pub notes: Vec<Vec<Note>>,
    pub ranges: Ranges,
}

struct Reader {
    le: bool,
}

impl Reader {
    fn u16(&self, buf: &[u8], off: usize) -> u16 {
        let b = [buf[off], buf[off + 1]];
        if self.le {
            u16::from_le_bytes(b)
        } else {
            u16::from_be_bytes(b)
        }
    }

    fn u32(&self, buf: &[u8], off: usize) -> u32 {
        let b = [buf[off], buf[off + 1], buf[off + 2], buf[off + 3]];
        if self.le {
            u32::from_le_bytes(b)
        } else {
            u32::from_be_bytes(b)
        }
    }

    fn u64(&self, buf: &[u8], off: usize) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&buf[off..off + 8]);
        if self.le {
            u64::from_le_bytes(b)
        } else {
            u64::from_be_bytes(b)
        }
    }
}

struct Layout {
    is64: bool,
    ehsize: usize,
    phentsize: usize,
    shentsize: usize,
}

const LAYOUT32: Layout = Layout {
    is64: false,
    ehsize: 52,
    phentsize: 32,
    shentsize: 40,
};

const LAYOUT64: Layout = Layout {
    is64: true,
    ehsize: 64,
    phentsize: 56,
    shentsize: 64,
};

pub fn parse(file: &[u8]) -> Result<Elf, String> {
    if file.len() < 16 {
        return Err("file is smaller than ELF header's e_ident".to_string());
    }

    if &file[0..4] != b"\x7fELF" {
        return Err("mismatched magic: not an ELF file".to_string());
    }

    let ident = Ident {
        class: file[4],
        data: file[5],
        version: file[6],
        abi: file[7],
        abi_ver: file[8],
    };

    let layout = match ident.class {
        ELFCLASS32 => &LAYOUT32,
        ELFCLASS64 => &LAYOUT64,
        x => return Err(format!("Unknown bitness: {}", x)),
    };

    let reader = match ident.data {
        ELFDATA2LSB => Reader { le: true },
        ELFDATA2MSB => Reader { le: false },
        x => return Err(format!("Unknown endianness: {}", x)),
    };

    if file.len() < layout.ehsize {
        return Err("file is smaller than ELF file header".to_string());
    }

    let mut ranges = Ranges::new(file.len());

    let ehdr = parse_ehdr(file, &reader, layout, &mut ranges);
    let phdrs = parse_phdrs(file, &reader, layout, &ehdr, &mut ranges);
    let shdrs = parse_shdrs(file, &reader, layout, &ehdr, &mut ranges);

    add_ident_ranges(&mut ranges);

    let section_names = read_section_names(file, &ehdr, &shdrs);
    let notes = parse_all_notes(file, &reader, &phdrs, &mut ranges);

    Ok(Elf {
        ident,
        ehdr,
        phdrs,
        shdrs,
        section_names,
        notes,
        ranges,
    })
}

fn parse_ehdr(file: &[u8], r: &Reader, layout: &Layout, ranges: &mut Ranges) -> Ehdr {
    let wsize = if layout.is64 { 8 } else { 4 };
    let addr = |off: usize| -> u64 {
        if layout.is64 {
            r.u64(file, off)
        } else {
            r.u32(file, off) as u64
        }
    };

    let mut off = 16;
    let e_type = r.u16(file, off);
    let e_type_off = off;
    off += 2;
    let e_machine = r.u16(file, off);
    let e_machine_off = off;
    off += 2;
    let e_version = r.u32(file, off);
    let e_version_off = off;
    off += 4;
    let e_entry = addr(off);
    let e_entry_off = off;
    off += wsize;
    let e_phoff = addr(off);
    let e_phoff_off = off;
    off += wsize;
    let e_shoff = addr(off);
    let e_shoff_off = off;
    off += wsize;
    let e_flags = r.u32(file, off);
    let e_flags_off = off;
    off += 4;
    let e_ehsize = r.u16(file, off);
    let e_ehsize_off = off;
    off += 2;
    let e_phentsize = r.u16(file, off);
    let e_phentsize_off = off;
    off += 2;
    let e_phnum = r.u16(file, off);
    let e_phnum_off = off;
    off += 2;
    let e_shentsize = r.u16(file, off);
    let e_shentsize_off = off;
    off += 2;
    let e_shnum = r.u16(file, off);
    let e_shnum_off = off;
    off += 2;
    let e_shstrndx = r.u16(file, off);
    let e_shstrndx_off = off;

    ranges.add(0, e_ehsize as usize, RangeType::Ehdr);
    ranges.add(e_type_off, 2, RangeType::Field("e_type"));
    ranges.add(e_machine_off, 2, RangeType::Field("e_machine"));
    ranges.add(e_version_off, 4, RangeType::Field("e_version"));
    ranges.add(e_entry_off, wsize, RangeType::Field("e_entry"));
    ranges.add(e_phoff_off, wsize, RangeType::Field("e_phoff"));
    ranges.add(e_shoff_off, wsize, RangeType::Field("e_shoff"));
    ranges.add(e_flags_off, 4, RangeType::Field("e_flags"));
    ranges.add(e_ehsize_off, 2, RangeType::Field("e_ehsize"));
    ranges.add(e_phentsize_off, 2, RangeType::Field("e_phentsize"));
    ranges.add(e_phnum_off, 2, RangeType::Field("e_phnum"));
    ranges.add(e_shentsize_off, 2, RangeType::Field("e_shentsize"));
    ranges.add(e_shnum_off, 2, RangeType::Field("e_shnum"));
    ranges.add(e_shstrndx_off, 2, RangeType::Field("e_shstrndx"));

    Ehdr {
        e_type,
        e_machine,
        e_version,
        e_entry,
        e_phoff,
        e_shoff,
        e_flags,
        e_ehsize,
        e_phentsize,
        e_phnum,
        e_shentsize,
        e_shnum,
        e_shstrndx,
    }
}

fn parse_phdrs(
    file: &[u8],
    r: &Reader,
    layout: &Layout,
    ehdr: &Ehdr,
    ranges: &mut Ranges,
) -> Vec<Phdr> {
    let mut phdrs = Vec::new();

    for i in 0..ehdr.e_phnum as usize {
        let start = (ehdr.e_phoff as usize).wrapping_add(i * layout.phentsize);
        let end = start.wrapping_add(layout.phentsize);
        let buf = &file[start..end];

        let phdr;

        if layout.is64 {
            phdr = Phdr {
                p_type: r.u32(buf, 0),
                p_flags: r.u32(buf, 4),
                p_offset: r.u64(buf, 8),
                p_vaddr: r.u64(buf, 16),
                p_paddr: r.u64(buf, 24),
                p_filesz: r.u64(buf, 32),
                p_memsz: r.u64(buf, 40),
                p_align: r.u64(buf, 48),
            };
        } else {
            phdr = Phdr {
                p_type: r.u32(buf, 0),
                p_offset: r.u32(buf, 4) as u64,
                p_vaddr: r.u32(buf, 8) as u64,
                p_paddr: r.u32(buf, 12) as u64,
                p_filesz: r.u32(buf, 16) as u64,
                p_memsz: r.u32(buf, 20) as u64,
                p_flags: r.u32(buf, 24),
                p_align: r.u32(buf, 28) as u64,
            };
        }

        if phdr.p_offset != 0 && phdr.p_filesz != 0 {
            ranges.add(
                phdr.p_offset as usize,
                phdr.p_filesz as usize,
                RangeType::Segment(i),
            );
        }

        ranges.add(start, layout.phentsize, RangeType::Phdr(i));

        if layout.is64 {
            ranges.add(start, 4, RangeType::Field("p_type"));
            ranges.add(start + 4, 4, RangeType::Field("p_flags"));
            ranges.add(start + 8, 8, RangeType::Field("p_offset"));
            ranges.add(start + 16, 8, RangeType::Field("p_vaddr"));
            ranges.add(start + 24, 8, RangeType::Field("p_paddr"));
            ranges.add(start + 32, 8, RangeType::Field("p_filesz"));
            ranges.add(start + 40, 8, RangeType::Field("p_memsz"));
            ranges.add(start + 48, 8, RangeType::Field("p_align"));
        } else {
            ranges.add(start, 4, RangeType::Field("p_type"));
            ranges.add(start + 4, 4, RangeType::Field("p_offset"));
            ranges.add(start + 8, 4, RangeType::Field("p_vaddr"));
            ranges.add(start + 12, 4, RangeType::Field("p_paddr"));
            ranges.add(start + 16, 4, RangeType::Field("p_filesz"));
            ranges.add(start + 20, 4, RangeType::Field("p_memsz"));
            ranges.add(start + 24, 4, RangeType::Field("p_flags"));
            ranges.add(start + 28, 4, RangeType::Field("p_align"));
        }

        phdrs.push(phdr);
    }

    phdrs
}

fn parse_shdrs(
    file: &[u8],
    r: &Reader,
    layout: &Layout,
    ehdr: &Ehdr,
    ranges: &mut Ranges,
) -> Vec<Shdr> {
    let mut shdrs = Vec::new();

    for i in 0..ehdr.e_shnum as usize {
        let start = (ehdr.e_shoff as usize).wrapping_add(i * layout.shentsize);
        let end = start.wrapping_add(layout.shentsize);
        let buf = &file[start..end];

        let shdr;

        if layout.is64 {
            shdr = Shdr {
                sh_name: r.u32(buf, 0),
                sh_type: r.u32(buf, 4),
                sh_flags: r.u64(buf, 8),
                sh_addr: r.u64(buf, 16),
                sh_offset: r.u64(buf, 24),
                sh_size: r.u64(buf, 32),
                sh_link: r.u32(buf, 40),
                sh_info: r.u32(buf, 44),
                sh_addralign: r.u64(buf, 48),
                sh_entsize: r.u64(buf, 56),
            };
        } else {
            shdr = Shdr {
                sh_name: r.u32(buf, 0),
                sh_type: r.u32(buf, 4),
                sh_flags: r.u32(buf, 8) as u64,
                sh_addr: r.u32(buf, 12) as u64,
                sh_offset: r.u32(buf, 16) as u64,
                sh_size: r.u32(buf, 20) as u64,
                sh_link: r.u32(buf, 24),
                sh_info: r.u32(buf, 28),
                sh_addralign: r.u32(buf, 32) as u64,
                sh_entsize: r.u32(buf, 36) as u64,
            };
        }

        if shdr.sh_offset != 0 && shdr.sh_size != 0 && shdr.sh_type != SHT_NOBITS {
            ranges.add(
                shdr.sh_offset as usize,
                shdr.sh_size as usize,
                RangeType::Section(i),
            );
        }

        ranges.add(start, layout.shentsize, RangeType::Shdr(i));

        if layout.is64 {
            ranges.add(start, 4, RangeType::Field("sh_name"));
            ranges.add(start + 4, 4, RangeType::Field("sh_type"));
            ranges.add(start + 8, 8, RangeType::Field("sh_flags"));
            ranges.add(start + 16, 8, RangeType::Field("sh_addr"));
            ranges.add(start + 24, 8, RangeType::Field("sh_offset"));
            ranges.add(start + 32, 8, RangeType::Field("sh_size"));
            ranges.add(start + 40, 4, RangeType::Field("sh_link"));
            ranges.add(start + 44, 4, RangeType::Field("sh_info"));
            ranges.add(start + 48, 8, RangeType::Field("sh_addralign"));
            ranges.add(start + 56, 8, RangeType::Field("sh_entsize"));
        } else {
            ranges.add(start, 4, RangeType::Field("sh_name"));
            ranges.add(start + 4, 4, RangeType::Field("sh_type"));
            ranges.add(start + 8, 4, RangeType::Field("sh_flags"));
            ranges.add(start + 12, 4, RangeType::Field("sh_addr"));
            ranges.add(start + 16, 4, RangeType::Field("sh_offset"));
            ranges.add(start + 20, 4, RangeType::Field("sh_size"));
            ranges.add(start + 24, 4, RangeType::Field("sh_link"));
            ranges.add(start + 28, 4, RangeType::Field("sh_info"));
            ranges.add(start + 32, 4, RangeType::Field("sh_addralign"));
            ranges.add(start + 36, 4, RangeType::Field("sh_entsize"));
        }

        shdrs.push(shdr);
    }

    shdrs
}

fn add_ident_ranges(ranges: &mut Ranges) {
    ranges.add(0, 16, RangeType::Ident);
    ranges.add(0, 4, RangeType::Field("magic"));
    ranges.add(4, 1, RangeType::Field("class"));
    ranges.add(5, 1, RangeType::Field("data"));
    ranges.add(6, 1, RangeType::Field("ver"));
    ranges.add(7, 1, RangeType::Field("abi"));
    ranges.add(8, 1, RangeType::Field("abi_ver"));
    ranges.add(9, 7, RangeType::Field("pad"));
}

/// Reads a NUL-terminated string at `off` from a string table.
fn read_str(strtab: &[u8], off: usize) -> String {
    let mut end = off;

    loop {
        crate::util::check_index(strtab.len(), end);

        if strtab[end] == 0 {
            break;
        }

        end += 1;
    }

    String::from_utf8(strtab[off..end].to_vec()).unwrap_or_default()
}

fn read_section_names(file: &[u8], ehdr: &Ehdr, shdrs: &[Shdr]) -> Vec<String> {
    let strndx = ehdr.e_shstrndx as usize;

    let strtab: Option<&[u8]> = if strndx != 0 && strndx < shdrs.len() {
        let sh = &shdrs[strndx];
        let start = sh.sh_offset as usize;
        let end = start.wrapping_add(sh.sh_size as usize);
        let slice = &file[start..end];

        if slice.is_empty() {
            None
        } else {
            Some(slice)
        }
    } else {
        None
    };

    shdrs
        .iter()
        .map(|sh| match strtab {
            Some(tab) => read_str(tab, sh.sh_name as usize),
            None => String::new(),
        })
        .collect()
}

fn align4(x: usize) -> usize {
    (x + 3) & !3
}

fn parse_notes(file: &[u8], r: &Reader, phdr: &Phdr, ranges: &mut Ranges) -> Vec<Note> {
    let mut notes = Vec::new();

    let start = phdr.p_offset as usize;
    let end = start.wrapping_add(phdr.p_filesz as usize);
    let data = &file[start..end];

    let mut pos = 0;

    while pos < data.len() {
        let rest = &data[pos..];

        let namesz = r.u32(&rest[0..4], 0) as usize;
        let descsz = r.u32(&rest[4..8], 0) as usize;
        let ntype = r.u32(&rest[8..12], 0);

        let name = &rest[12..12 + namesz];
        let desc = &rest[12 + namesz..12 + namesz + descsz];

        let size = align4(12 + namesz + descsz);

        ranges.add(start + pos, size, RangeType::Subrange);

        notes.push(Note {
            name: name.to_vec(),
            desc: desc.to_vec(),
            ntype,
        });

        pos += size;
    }

    notes
}

fn parse_all_notes(
    file: &[u8],
    r: &Reader,
    phdrs: &[Phdr],
    ranges: &mut Ranges,
) -> Vec<Vec<Note>> {
    let mut all = Vec::new();

    for phdr in phdrs {
        if phdr.p_type == PT_NOTE && phdr.p_offset != 0 {
            all.push(parse_notes(file, r, phdr, ranges));
        } else {
            all.push(Vec::new());
        }
    }

    all
}
