use crate::elf::{Elf, Note, PT_INTERP, PT_NOTE, SHT_STRTAB};
use crate::names;
use crate::util::{escape_ascii_char, human_size, render_bytes};

const T_HEAD: &str = include_str!("../templates/01_head.html");
const T_AFTER_TITLE: &str = include_str!("../templates/02_after_title.html");
const T_BEFORE_OFFSETS: &str = include_str!("../templates/03_before_offsets.html");
const T_BEFORE_BYTES: &str = include_str!("../templates/04_before_bytes.html");
const T_BEFORE_ASCII: &str = include_str!("../templates/05_before_ascii.html");
const T_BEFORE_INFOTABLES1: &str = include_str!("../templates/06_before_infotables1.html");
const T_BETWEEN_INFOTABLES: &str = include_str!("../templates/07_between_infotables.html");
const T_AFTER_INFOTABLES: &str = include_str!("../templates/08_after_infotables.html");
const T_AFTER_FILELEN: &str = include_str!("../templates/09_after_filelen.html");
const T_TAIL: &str = include_str!("../templates/10_tail.html");

/// Hexadecimal number with decimal value in the tooltip.
fn fmt_hex(v: u64) -> String {
    format!("<span class='number' title='{}'>0x{:x}</span>", v, v)
}

/// Decimal number with hexadecimal value in the tooltip.
fn fmt_dec(v: u64) -> String {
    format!("<span class='number' title='0x{:x}'>{}</span>", v, v)
}

/// Decimal size with hexadecimal tooltip and human readable value when large.
fn fmt_size(v: u64) -> String {
    if v >= 1024 {
        format!(
            "<span class='number' title='0x{:x}'>{} ({})</span>",
            v,
            v,
            human_size(v)
        )
    } else {
        fmt_dec(v)
    }
}

fn fmt_file_size(v: u64) -> String {
    if v >= 1024 {
        format!("{} ({} B)", human_size(v), v)
    } else {
        format!("{} B", v)
    }
}

fn file_info(elf: &Elf, file: &[u8], path: &str) -> String {
    let mut s = String::new();
    let ehdr = &elf.ehdr;
    let ident = &elf.ident;

    let row = |cls: &str, label: &str, value: &str| -> String {
        format!(
            "      <tr class='fileinfo_{}'> <td>{}</td> <td>{}</td> </tr>\n",
            cls, label, value
        )
    };

    s += &row("file_name", "File name:", path);
    s += &row("file_size", "File size:", &fmt_file_size(file.len() as u64));

    let class = match ident.class {
        crate::elf::ELFCLASS32 => "32-bit",
        _ => "64-bit",
    };
    s += &row("class", "Object class:", class);

    let data = match ident.data {
        crate::elf::ELFDATA2LSB => "Little endian",
        _ => "Big endian",
    };
    s += &row("data", "Data encoding:", data);

    s += &row("abi", "ABI:", &names::abi(ident.abi));

    if ident.abi_ver != 0 {
        s += &row(
            "abi_ver",
            "Uncommon ABI version(!):",
            &ident.abi_ver.to_string(),
        );
    }

    s += &row("e_type", "Type:", &names::e_type(ehdr.e_type));
    s += &row("e_machine", "Architecture:", &names::e_machine(ehdr.e_machine));
    s += &row("e_entry", "Entrypoint:", &fmt_hex(ehdr.e_entry));

    let ph = format!(
        "<span title='0x{:x}' class='number fileinfo_e_phnum'>{}</span> * \
         <span title='0x{:x}' class='number fileinfo_e_phentsize'>{}</span> @ \
         <span title='0x{:x}' class='number fileinfo_e_phoff'>{}</span>",
        ehdr.e_phnum, ehdr.e_phnum, ehdr.e_phentsize, ehdr.e_phentsize, ehdr.e_phoff, ehdr.e_phoff
    );
    s += &row("ph", "Program headers:", &ph);

    let sh = format!(
        "<span title='0x{:x}' class='number fileinfo_e_shnum'>{}</span> * \
         <span title='0x{:x}' class='number fileinfo_e_shentsize'>{}</span> @ \
         <span title='0x{:x}' class='number fileinfo_e_shoff'>{}</span>",
        ehdr.e_shnum, ehdr.e_shnum, ehdr.e_shentsize, ehdr.e_shentsize, ehdr.e_shoff, ehdr.e_shoff
    );
    s += &row("sh", "Section headers:", &sh);

    if ehdr.e_flags != 0 {
        s += &row("e_flags", "Flags:", &format!("0x{:x}", ehdr.e_flags));
    }

    s
}

fn offsets(file: &[u8]) -> String {
    let mut s = String::new();

    for i in 0..file.len() {
        if i % 16 == 0 {
            s += &format!("{:x}", i);
        }
        if i % 16 == 15 {
            s.push('\n');
        }
    }

    s
}

fn dump(elf: &Elf, file: &[u8]) -> String {
    let mut s = String::with_capacity(file.len() * 4);

    for (i, &b) in file.iter().enumerate() {
        if i > 0 {
            if i % 16 == 0 {
                s.push('\n');
            } else {
                s.push(' ');
            }
        }

        if let Some(starts) = elf.ranges.starts_at(i) {
            for t in starts {
                s += "<span class='";
                s += &t.class();
                s += "'>";
            }
        }

        if i < 4 && b.is_ascii_graphic() {
            s += "&nbsp;";
            s.push(b as char);
        } else {
            s += &format!("{:02x}", b);
        }

        for _ in 0..elf.ranges.ends_at(i) {
            s += "</span>";
        }
    }

    s
}

fn ascii(file: &[u8]) -> String {
    let mut s = String::with_capacity(file.len() + file.len() / 16 + 1);

    for (i, &b) in file.iter().enumerate() {
        if b.is_ascii_graphic() {
            s += &escape_ascii_char(b);
        } else {
            s.push('.');
        }

        if i % 16 == 15 {
            s.push('\n');
        }
    }

    s
}

fn irow(label: &str, value: &str) -> String {
    format!("            <tr> <td>{}</td> <td>{}</td> </tr>\n", label, value)
}

fn phdr_tables(elf: &Elf) -> String {
    let mut s = String::new();

    for (i, phdr) in elf.phdrs.iter().enumerate() {
        s += &format!("          <table class='conceal itable' id='info_phdr{}'>\n", i);
        s += "          <th colspan='2' class='phdr_itable'></th>\n";
        s += &irow("Type:", &names::p_type(phdr.p_type));
        s += &irow("Flags:", &names::p_flags(phdr.p_flags));
        s += &irow("Offset in file:", &fmt_hex(phdr.p_offset));
        s += &irow("Size in file:", &fmt_size(phdr.p_filesz));
        s += &irow("Vaddr in memory:", &fmt_hex(phdr.p_vaddr));
        s += &irow("Size in memory:", &fmt_size(phdr.p_memsz));
        s += &irow("Alignment:", &fmt_hex(phdr.p_align));
        s += "          </table>\n";
    }

    s
}

fn shdr_tables(elf: &Elf) -> String {
    let mut s = String::new();

    for (i, shdr) in elf.shdrs.iter().enumerate() {
        s += &format!("          <table class='conceal itable' id='info_shdr{}'>\n", i);
        s += "          <th colspan='2' class='shdr_itable'></th>\n";
        s += &irow("Index:", &i.to_string());
        s += &irow("Name:", &elf.section_names[i]);
        s += &irow("Type:", &names::sh_type(shdr.sh_type));
        s += &irow("Flags:", &names::sh_flags(shdr.sh_flags));
        s += &irow("Vaddr in memory:", &fmt_hex(shdr.sh_addr));
        s += &irow("Offset in file:", &fmt_hex(shdr.sh_offset));
        s += &irow("Size in file:", &fmt_size(shdr.sh_size));
        s += &irow("Linked section:", &shdr.sh_link.to_string());
        s += &irow("Extra info:", &fmt_dec(shdr.sh_info as u64));
        s += &irow("Alignment:", &fmt_hex(shdr.sh_addralign));
        s += &irow("Size of entries:", &fmt_size(shdr.sh_entsize));
        s += "          </table>\n";
    }

    s
}

fn note_rows(notes: &[Note]) -> String {
    let mut s = String::new();

    for (i, note) in notes.iter().enumerate() {
        if i > 0 {
            s += "            <tr> <td><br></td> </tr>\n";
        }

        let name_len = note.name.len().saturating_sub(1);
        s += &irow("Name:", &render_bytes(&note.name[..name_len]));
        s += &irow("Type:", &format!("0x{:x}", note.ntype));

        if note.ntype == 3 {
            let mut hex = String::new();
            for b in &note.desc {
                hex += &format!("{:02x}", b);
            }
            s += &irow("Build ID:", &hex);
        } else {
            s += &irow("Desc:", &render_bytes(&note.desc));
        }
    }

    s
}

fn segment_tables(elf: &Elf, file: &[u8]) -> String {
    let mut s = String::new();

    for (i, phdr) in elf.phdrs.iter().enumerate() {
        s += &format!(
            "          <table class='conceal itable' id='info_segment{}'>\n",
            i
        );
        s += "          <th colspan='2' class='segment_itable'></th>\n";
        s += &irow("Type:", &names::p_type(phdr.p_type));
        s += &irow("Size in file:", &fmt_size(phdr.p_filesz));
        s += &irow("Size in memory:", &fmt_size(phdr.p_memsz));

        if phdr.p_type == PT_INTERP {
            let start = phdr.p_offset as usize;
            let end = start
                .wrapping_add(phdr.p_filesz as usize)
                .wrapping_sub(1);
            let interp = &file[start..end];

            s += "            <tr><td><br></td></tr>\n";
            s += &irow("Interpreter:", &render_bytes(interp));
        } else if phdr.p_type == PT_NOTE {
            s += "            <tr><td><br></td></tr>\n";
            s += &note_rows(&elf.notes[i]);
        }

        s += "          </table>\n";
    }

    s
}

/// Collects strings from a string table section.
fn strtab_strings(data: &[u8]) -> Vec<String> {
    let mut strings = Vec::new();
    let mut prev_nul: Option<usize> = None;
    let mut first = true;

    for (i, &b) in data.iter().enumerate() {
        if b != 0 {
            continue;
        }

        let piece: &[u8] = if first {
            first = false;
            &data[0..std::cmp::min(1, i)]
        } else {
            let start = prev_nul.unwrap() + 1;
            &data[start..i]
        };

        prev_nul = Some(i);

        if piece.is_empty() {
            continue;
        }

        if let Ok(st) = std::str::from_utf8(piece) {
            strings.push(st.to_string());
        }
    }

    strings
}

fn section_tables(elf: &Elf, file: &[u8]) -> String {
    let mut s = String::new();

    for (i, shdr) in elf.shdrs.iter().enumerate() {
        s += &format!(
            "          <table class='conceal itable' id='info_section{}'>\n",
            i
        );
        s += "          <th colspan='2' class='section_itable'></th>\n";
        s += &irow("Type:", &names::sh_type(shdr.sh_type));
        s += &irow("Size:", &fmt_size(shdr.sh_size));

        if shdr.sh_type == SHT_STRTAB {
            let start = shdr.sh_offset as usize;
            let end = start.wrapping_add(shdr.sh_size as usize);
            let data = &file[start..end];

            s += "            <tr><td><br></td></tr>\n";
            s += "            <tr>\n";
            s += "              <td></td>\n";
            s += "              <td>\n";
            s += "                <div>\n";

            for st in strtab_strings(data) {
                s += "                  ";
                s += &st;
                s += "\n";
            }

            s += "                </div>\n";
            s += "              </td>\n";
            s += "            </tr>\n";
        }

        s += "          </table>\n";
    }

    s
}

fn connects(elf: &Elf) -> String {
    let mut s = String::new();

    s += "      connect('.e_phoff', '.bin_phdr0');\n";
    s += "      connect('.e_shoff', '.bin_shdr0');\n";

    for i in 0..elf.phdrs.len() {
        s += &format!(
            "      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');\n",
            i, i
        );
    }

    for (i, shdr) in elf.shdrs.iter().enumerate() {
        s += &format!(
            "      connect('.bin_shdr{} > .sh_offset', '.bin_section{}');\n",
            i, i
        );

        if shdr.sh_link != 0 {
            s += &format!(
                "      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');\n",
                i, shdr.sh_link
            );
        }
    }

    s
}

pub fn generate(elf: &Elf, file: &[u8], path: &str, basename: &str) -> String {
    let mut html = String::with_capacity(file.len() * 5 + 32 * 1024);

    html += T_HEAD;
    html += basename;
    html += T_AFTER_TITLE;
    html += &file_info(elf, file, path);
    html += T_BEFORE_OFFSETS;
    html += &offsets(file);
    html += T_BEFORE_BYTES;
    html += &dump(elf, file);
    html += T_BEFORE_ASCII;
    html += &ascii(file);
    html += T_BEFORE_INFOTABLES1;
    html += &phdr_tables(elf);
    html += &shdr_tables(elf);
    html += T_BETWEEN_INFOTABLES;
    html += &segment_tables(elf, file);
    html += &section_tables(elf, file);
    html += T_AFTER_INFOTABLES;
    html += &file.len().to_string();
    html += T_AFTER_FILELEN;
    html += &connects(elf);
    html += T_TAIL;

    html
}
