use std::collections::HashMap;

#[derive(Clone, Debug)]
pub enum RangeType {
    Ehdr,
    Ident,
    Field(&'static str),
    Phdr(usize),
    Shdr(usize),
    Segment(usize),
    Section(usize),
    Subrange,
}

impl RangeType {
    pub fn class(&self) -> String {
        match self {
            RangeType::Ehdr => "ehdr".to_string(),
            RangeType::Ident => "ident".to_string(),
            RangeType::Field(name) => name.to_string(),
            RangeType::Phdr(i) => format!("bin_phdr{} phdr", i),
            RangeType::Shdr(i) => format!("bin_shdr{} shdr", i),
            RangeType::Segment(i) => format!("bin_segment{} segment", i),
            RangeType::Section(i) => format!("bin_section{} section hover", i),
            RangeType::Subrange => "segment_subrange hover".to_string(),
        }
    }
}

const HAS_START: u8 = 1;
const HAS_END: u8 = 2;

/// Keeps track of highlighted byte ranges of the file. Starts are kept in
/// insertion order per offset; ends are only counted.
pub struct Ranges {
    len: usize,
    flags: Vec<u8>,
    starts: HashMap<usize, Vec<RangeType>>,
    ends: HashMap<usize, usize>,
}

impl Ranges {
    pub fn new(len: usize) -> Ranges {
        Ranges {
            len,
            flags: vec![0; len],
            starts: HashMap::new(),
            ends: HashMap::new(),
        }
    }

    pub fn add(&mut self, start: usize, size: usize, t: RangeType) {
        let end = start.wrapping_add(size).wrapping_sub(1);

        crate::util::check_index(self.len, start);
        crate::util::check_index(self.len, end);

        self.flags[start] |= HAS_START;
        self.flags[end] |= HAS_END;
        self.starts.entry(start).or_default().push(t);
        *self.ends.entry(end).or_default() += 1;
    }

    pub fn starts_at(&self, off: usize) -> Option<&Vec<RangeType>> {
        if self.flags[off] & HAS_START == 0 {
            return None;
        }
        self.starts.get(&off)
    }

    pub fn ends_at(&self, off: usize) -> usize {
        if self.flags[off] & HAS_END == 0 {
            return 0;
        }
        self.ends.get(&off).copied().unwrap_or(0)
    }
}
